import { copy } from './i18n.mjs';
copy.en.privacy = 'When you request a check, your URL is sent to Arcdrake’s scanner. It fetches at most six public responses, including redirects, an HTTP variant and up to two linked first-party JS/CSS files. Target websites see the scanner’s requests and outgoing IP address. Inputs and redacted results are processed in memory; they are not deliberately saved. For abuse protection, the scanner keeps a daily pseudonymous client key and target hostname for up to two minutes. Hosting providers process connection data separately. Do not submit private or signed links. Optional usage counts are separate and never include your URL or results.';
copy.de.privacy = 'Wenn du eine Prüfung anforderst, wird deine URL an den Scanner von Arcdrake gesendet. Er ruft höchstens sechs öffentliche Antworten ab, einschließlich Weiterleitungen, einer HTTP-Variante und bis zu zwei verlinkten JS/CSS-Dateien derselben Herkunft. Zielwebsites sehen die Anfragen und die ausgehende IP-Adresse des Scanners. Eingaben und maskierte Ergebnisse werden im Arbeitsspeicher verarbeitet und nicht gezielt gespeichert. Zum Missbrauchsschutz hält der Scanner einen täglich wechselnden pseudonymen Client-Schlüssel und den Zielhostnamen für bis zu zwei Minuten vor. Hostinganbieter verarbeiten Verbindungsdaten gesondert. Keine privaten oder signierten Links eingeben. Optionale Nutzungszählungen sind getrennt und enthalten niemals deine URL oder Ergebnisse.';
copy.en.help = 'Public HTTP/HTTPS only. Your URL goes to the Arcdrake scanner; the target sees its requests. Never enter private or signed URLs. Masking is heuristic. Results can take a moment or be inconclusive.';
copy.de.help = 'Nur öffentliches HTTP/HTTPS. Deine URL geht an den Arcdrake-Scanner; die Zielwebsite sieht seine Anfragen. Keine privaten oder signierten URLs eingeben. Die Maskierung ist heuristisch. Ergebnisse können dauern oder unklar bleiben.';
copy.en.footer = 'An Arcdrake tool · English & Deutsch';
copy.de.footer = 'Ein Werkzeug von Arcdrake · English & Deutsch';
copy.en.notes.unavailable = 'The checker is unavailable. Your URL has not been confirmed as checked. Please try later.';
copy.de.notes.unavailable = 'Die Website-Prüfung ist nicht verfügbar. Eine Prüfung deiner URL wurde nicht bestätigt. Bitte später erneut versuchen.';
copy.en.notes.daily_capacity = 'Today’s shared check allowance has been reached. Please try again after 00:00 UTC.';
copy.de.notes.daily_capacity = 'Das gemeinsame Tageskontingent ist aufgebraucht. Bitte nach 00:00 UTC erneut versuchen.';
copy.en.limits = 'Public hostnames on standard HTTP/HTTPS ports only; numeric IP URLs are not supported. At most six responses of 256 KiB each and 25 seconds per scan. JavaScript is not executed. Login pages, challenges, compression and unusual encodings can make results inconclusive. Certificate expiry and certificate-chain details are not checked. The shared allowance is 100 attempts per UTC day; capacity is not guaranteed.';
copy.de.limits = 'Nur öffentliche Hostnamen über Standardports für HTTP/HTTPS; numerische IP-URLs werden nicht unterstützt. Höchstens sechs Antworten mit je 256 KiB und 25 Sekunden pro Prüfung. JavaScript wird nicht ausgeführt. Anmeldungen, Schutzseiten, Komprimierung und ungewöhnliche Kodierungen können unklare Ergebnisse liefern. Zertifikatsablauf und Zertifikatsketten werden nicht geprüft. Das gemeinsame Kontingent beträgt 100 Versuche pro UTC-Tag; Verfügbarkeit ist nicht garantiert.';
copy.en.notes.certificate_unavailable = 'Certificate expiry and certificate-chain details were not inspected. HTTPS connectivity alone is not a complete TLS assessment.';
copy.de.notes.certificate_unavailable = 'Zertifikatsablauf und Zertifikatsketten wurden nicht geprüft. HTTPS-Erreichbarkeit allein ist keine vollständige TLS-Bewertung.';
copy.en.notes.hostname_required = 'Enter a public hostname. Numeric IP URLs are not supported by this hosted checker.';
copy.de.notes.hostname_required = 'Bitte einen öffentlichen Hostnamen eingeben. Numerische IP-URLs werden von dieser gehosteten Prüfung nicht unterstützt.';
copy.en.notes.header_limit = 'Response headers exceeded the supported size; the response was not inspected.';
copy.de.notes.header_limit = 'Die Antwortheader überschritten die unterstützte Größe; die Antwort wurde nicht geprüft.';
export { copy };
